#include <bits/stdc++.h>
using namespace std;
int main() {
  int N;
  cin >> N;
  vector<int> L(N);
  for (int &l : L) cin >> l;
  int ans = 1000000000;
  for (int i = 1; i < N; i++) {
    int sum_l = 0, sum_r = 0;
    for (int j = 0; j < i; j++) sum_l += L[j];
    for (int j = i; j < N; j++) sum_r += L[j];
    ans = min(ans, abs(sum_l - sum_r));
  }
  cout << ans << endl;
}
N = int(input())
L = list(map(int, input().split()))
ans = min(abs(sum(L[:i]) - sum(L[i:])) for i in range(1, N))
print(ans)
